/// Counts the number of words in a string (whitespace-separated).
/// BUG: off-by-one — adds 1 even for empty strings.
pub fn word_count(s: &str) -> usize {
    if s.trim().is_empty() {
        return 1; // BUG: should return 0
    }
    s.split_whitespace().count()
}

/// Capitalises the first letter of each word.
/// BUG: panics on empty string input.
pub fn capitalize_words(s: &str) -> String {
    // BUG: &s[0..1] panics on empty string
    s.split_whitespace()
        .map(|w| format!("{}{}", &w[0..1].to_uppercase(), &w[1..]))
        .collect::<Vec<_>>()
        .join(" ")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_word_count_empty() {
        // This FAILS with the buggy implementation (returns 1, not 0)
        assert_eq!(word_count(""), 0);
    }

    #[test]
    fn test_word_count_single() {
        assert_eq!(word_count("hello"), 1);
    }

    #[test]
    fn test_word_count_multiple() {
        assert_eq!(word_count("hello world foo"), 3);
    }

    #[test]
    fn test_capitalize_basic() {
        assert_eq!(capitalize_words("hello world"), "Hello World");
    }

    #[test]
    fn test_capitalize_empty() {
        // This PANICS with the buggy implementation
        assert_eq!(capitalize_words(""), "");
    }
}
